def sum_of_sublist(numbers, start_index, end_index):
    """
    Returns the sum of a sublist defined by the starting and ending indices.
    If the starting index is greater than the ending index, returns None.
    """
    if start_index > end_index:
        return None
    return sum(numbers[start_index:end_index+1])
